import time
from fly.data import data_proxy
from IQCommon import pandas as pd
def calc_trade_days(startTime, endTime):
    holiday = data_proxy().get_holiday_local()
    daterange = pd.date_range(start=startTime, end=endTime, freq='B')
    tradeDays = []
    for item in daterange:
        nowdate = item.strftime('%Y%m%d')
        if nowdate in holiday:
            continue
        timestamp = int(time.mktime(item.timetuple()))
        tradeDays.append(timestamp)
    else:
        return tradeDays
